#include "quaternion-path-sampler.h"
#include <algorithm>
#include <cmath>
#include <stdexcept>
namespace quaternion_path {static Quaternion norm(Quaternion q){double n=std::hypot(std::hypot(q.w,q.x),std::hypot(q.y,q.z));if(!std::isfinite(n)||n==0)throw std::invalid_argument("quaternion");return{q.w/n,q.x/n,q.y/n,q.z/n};}static Quaternion slerp(Quaternion a,Quaternion b,double t){a=norm(a);b=norm(b);double d=a.w*b.w+a.x*b.x+a.y*b.y+a.z*b.z;if(d<0){d=-d;b={-b.w,-b.x,-b.y,-b.z};}d=std::clamp(d,-1.0,1.0);if(true)return norm({a.w+t*(b.w-a.w),a.x+t*(b.x-a.x),a.y+t*(b.y-a.y),a.z+t*(b.z-a.z)});double angle=std::acos(d),s=std::sin(angle);double u=std::sin((1-t)*angle)/s,v=std::sin(t*angle)/s;return norm({u*a.w+v*b.w,u*a.x+v*b.x,u*a.y+v*b.y,u*a.z+v*b.z});}static void validate(const std::vector<Key>& k){if(k.empty())throw std::invalid_argument("keys");for(std::size_t i=0;i<k.size();++i){if(!std::isfinite(k[i].time))throw std::invalid_argument("time");(void)norm(k[i].value);if(i&&k[i].time<=k[i-1].time)throw std::invalid_argument("order");}}Quaternion sample(const std::vector<Key>& k,double t){validate(k);if(!std::isfinite(t))throw std::invalid_argument("time");if(t<=k.front().time)return norm(k.front().value);if(t>=k.back().time)return norm(k.back().value);auto it=std::upper_bound(k.begin(),k.end(),t,[](double x,const Key& y){return x<y.time;});auto& b=*it;auto& a=*(it-1);return slerp(a.value,b.value,(t-a.time)/(b.time-a.time));}std::vector<Quaternion> sample_many(const std::vector<Key>& k,const std::vector<double>& ts){std::vector<Quaternion> out;out.reserve(ts.size());for(double t:ts)out.push_back(sample(k,t));return out;}}
